insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Algorithm and Code Training School (ACTS) 2027.1, Пафос, Кипър', 'Интензивен 11-дневен лагер по състезателно програмиране за ученици на 16–19 години със силни резултати от национални или международни състезания. Организатори: Constructor University, Neapolis University Pafos и JetBrains Foundation. Провежда се 15–25 март 2027 г. в Пафос, Кипър, на английски език. Подборът е по резултатите от входното състезание Youth Coding Challenge на 29 ноември 2026 г. (Codeforces, с прокторинг) и по досегашните постижения. Срок за регистрация: 28 ноември 2026 г. Решение: 18 декември 2026 г. Такса за лагера: 100 EUR; настаняване, храна и програма са покрити, пътуването не е.', null, 'https://lp.jetbrains.media/academy/acts/2027.1/', null, false, 'school'::public.audience, '2027-03-15T00:00:00+02:00', '2027-03-25T23:59:00+02:00', '2026-11-28T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://lp.jetbrains.media/academy/acts/2027.1/')
