insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'AmCham Bulgaria Hackathon 2026', 'Хакатон на Американската търговска камара в България с ТУ – София, Стопанския факултет на СУ „Св. Климент Охридски“, ХТМУ и Физико-технологичния факултет на Пловдивския университет. Отбори от студенти работят три седмици по реални бизнес казуси на компании (A1, IBM, Sensata, Enery, RingCentral, HPE и др.) с ментори от бизнеса и представят решенията пред жури. Провежда се 13 март – 30 април 2026 г.; записване от 19 февруари до 16 март 2026 г. Критерии: Power BI, AI и машинно обучение, анализ на данни, стратегическо мислене, работа в екип. Награди: BIG Winner, Best Team, Most Innovative Solution.', null, 'https://amcham.bg/amchamevents/amcham-bulgaria-hackathon-2026/', 'София', false, 'university'::public.audience, '2026-03-13T00:00:00+02:00', '2026-04-30T23:59:00+03:00', '2026-03-16T23:59:00+02:00', 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://amcham.bg/amchamevents/amcham-bulgaria-hackathon-2026/')
