insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'XXIX Национален конкурс „Космосът — настояще и бъдеще на човечеството“', 'Национален конкурс на Фондация „Еврика“ за ученици от 8 до 19 години, под патронажа на първия български космонавт ген. Георги Иванов и включен в програмата на МОН за извънкласни дейности. Пет направления: идеи за научни и технически експерименти (14–19 г.), модели и макети на космически обекти (10–19 г.), графични произведения, създадени с компютър (10–19 г.), литературни творби на космическа тема – есета, разкази, стихотворения (8–19 г.) и рисунки „Човекът и Космосът“ (8–19 г.). Награди от 70 € до 100 €. Конкурсът е задочен; работите се изпращат по пощата до Фондация „Еврика“, София. Срок за изпращане: 24 май 2027 г. Резултати: юли 2027 г. Награждаване: 1 ноември 2027 г.', null, 'https://evrika.org/bg/space', 'София', false, 'school'::public.audience, null, null, '2027-05-24T23:59:00+03:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://evrika.org/bg/space')
