insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('scholarship'::public.opportunity_type, null, 'Именни стипендии „Еврика“ за студенти (1 600 € годишно)', 'Фондация „Еврика“ дава всяка година 11 именни стипендии по 1 600 € (плюс стипендия „Акад. Александър Теодоров-Балан“) за български студенти в български университети в областите информатика, математика, физика, химия, медицина и биология, аграрни науки, електроника и електротехника, машинни технологии, строителство и архитектура, икономика, изчислителна математика и българска филология. Изисквания: завършен поне втори курс, среден успех поне 5,00, редовно обучение. Документите се подават от 1 септември до 15 октомври; за 2026/2027 г. срокът е изтекъл и резултатите се обявяват на 30 ноември. Ученици и студенти с медали от международни олимпиади по математика, информатика, физика, химия и биология получават стипендия по право (850 € – 1 050 €).', null, 'https://evrika.org/bg/scholarships', 'София', false, 'both'::public.audience, null, null, '2026-10-15T23:59:00+03:00', 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://evrika.org/bg/scholarships')
