insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('scholarship'::public.opportunity_type, null, 'Opportunity Funds – Bulgaria 2027: стипендии до $5000 за ученици в 10. и 11. клас', 'Комисия „Фулбрайт“ обявява конкурс за до 20 стипендии в размер до $5000 всяка за подготовка на талантливи ученици в 10. и 11. клас за кандидатстване в акредитирани американски колежи и университети и отпътуване в САЩ. Тази година приоритет имат кандидати със STEM профил. Стипендията покрива такси за TOEFL / IELTS и SAT, обучителен модул за писане на есе, такси за кандидатстване, виза, самолетен билет и едномесечна стипендия. Изисквания: редовни ученици в 10. или 11. клас в България, българско гражданство, отличен английски и отличен успех, нужда от финансова помощ (доход под 1200 евро на член от семейството). Документите се изпращат по имейл до 6 декември 2026 г. Интервюта: 14–18 декември 2026 г. Обявяване на номинираните: 21 декември 2026 г.', null, 'https://www.fulbright.bg/konkurs-opportunity-funds-bulgaria/', null, true, 'school'::public.audience, null, null, '2026-12-06T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.fulbright.bg/konkurs-opportunity-funds-bulgaria/')
