insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('scholarship'::public.opportunity_type, null, 'Стипендии „Фулбрайт“ за изследователска дейност на докторанти в САЩ (2027–28)', 'Програмата „Фулбрайт“ дава възможност на докторанти в напреднал етап на редовна или задочна докторантура да работят 4–6 месеца в университети и институти в САЩ. Допускат се всички области на науката и изкуствата без клинична медицина и стоматология. Всяка година се дават 3–4 стипендии. Стипендията покрива месечна издръжка, самолетен билет и здравна застраховка. Изисквания: българско гражданство, отличен английски (TOEFL поне 81 т.), три препоръки. Краен срок за кандидатстване: 4 декември 2026 г. Интервютата са онлайн в средата на декември. Начало на програмата: най-рано август 2027 г.', null, 'https://www.fulbright.bg/doktoranti-research/', null, true, 'university'::public.audience, null, null, '2026-12-04T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.fulbright.bg/doktoranti-research/')
