insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('scholarship'::public.opportunity_type, null, 'Стипендии Google DeepMind AI Masters за магистри по изкуствен интелект (СУ, институт GATE)', 'Институтът GATE към Софийския университет „Св. Климент Охридски“ с Факултета по математика и информатика дава две пълни стипендии Google DeepMind AI Masters Scholarships за академичната 2026–2027 г. Всяка покрива 18-месечно обучение (около 28 700 щатски долара): такси, настаняване и издръжка, оборудване, академични пътувания и конференции по изкуствен интелект. За студенти, приети в магистърските програми „Изкуствен интелект“, „Извличане на информация и откриване на знания“ и „Технологии за големи данни“; минимален успех 4,50 от бакалавърската степен. Краен срок: 9 октомври 2026 г.; подбор до 31 октомври 2026 г.', null, 'https://www.bta.bg/bg/news/1166509', 'София', false, 'university'::public.audience, null, null, '2026-10-09T23:59:00+03:00', 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.bta.bg/bg/news/1166509')
