insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('scholarship'::public.opportunity_type, null, 'Годишна докторантска стипендия 5 000 евро на фондация „Карол Знание“', 'Фондация „Карол Знание“ дава годишна докторантска стипендия от 5 000 евро на изявен редовен докторант. Изисквания: българско гражданство, редовен докторант в акредитирано висше училище или БАН, да не е последна година на обучението, проект с потенциално практическо приложение в естествените, техническите или медицинските науки. Кандидатури се приемат до 13 декември 2026 г. по имейл (knowledge@karoll.bg): CV, мотивационно писмо, резюме на проекта и заповед за зачисляване. Финалистите презентират на финала на 13 януари 2027 г. Стипендията се изплаща февруари – ноември на десет месечни вноски.', null, 'https://www.karollknowledge.bg/phd', null, false, 'university'::public.audience, null, null, '2026-12-13T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.karollknowledge.bg/phd')
on conflict (source_url) do update set type = excluded.type, organizer_id = excluded.organizer_id, title = excluded.title, description = excluded.description, image_url = excluded.image_url, external_url = excluded.external_url, city = excluded.city, is_online = excluded.is_online, audience = excluded.audience, starts_at = excluded.starts_at, ends_at = excluded.ends_at, deadline_at = excluded.deadline_at, status = excluded.status, source = excluded.source;
