insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'Създай въздействие: 1 500 евро награда за прототип (ТУ – София)', 'Отворено е кандидатстването в конкурса „Създай въздействие“ на Центъра за устойчиво развитие на Технически университет – София. Наградата от 1 500 евро за създаване на прототип се осигурява от фондация „Карол Знание“. През академичната година се връчват три награди за иновативни идеи с принос към устойчивото развитие и кръговата икономика. Могат да кандидатстват всички студенти и докторанти на ТУ – София, а победителите печелят и място в програмата „Предприемачи в науката 2027“. Крайният срок за кандидатстване в настоящата сесия е 31 декември 2026 г.', null, 'https://www.karollknowledge.bg/създай-въздействие', 'София', false, 'university'::public.audience, null, null, '2026-12-31T23:59:00+02:00', 'published'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://www.karollknowledge.bg/articles/създай-въздействие/1-500-евро-награда-за-прототип')
on conflict (source_url) do update set type = excluded.type, organizer_id = excluded.organizer_id, title = excluded.title, description = excluded.description, image_url = excluded.image_url, external_url = excluded.external_url, city = excluded.city, is_online = excluded.is_online, audience = excluded.audience, starts_at = excluded.starts_at, ends_at = excluded.ends_at, deadline_at = excluded.deadline_at, status = excluded.status, source = excluded.source;
