insert into public.opportunities (type, organizer_id, title, description, image_url, external_url, city, is_online, audience, starts_at, ends_at, deadline_at, status, source, source_url) values ('competition'::public.opportunity_type, null, 'LiberHack Edition 1 – хакатон, Бургас', 'Първото издание на хакатона LiberHack за младежи от 14 до 21 години се проведе на 5–7 юни 2026 г. в ППМГ „Акад. Никола Обрешков“, Бургас, в училищни кабинети. 44 участници на място в 15 отбора работиха 48 часа и защитиха пред журито работещи продукти, не слайдове. Раздадени награди: 1200 €.', null, 'https://liberhack.org/', 'Бургас', false, 'both'::public.audience, '2026-06-05T00:00:00+03:00', '2026-06-07T23:59:00+03:00', null, 'archived'::public.opportunity_status, 'scraper'::public.opportunity_source, 'https://liberhack.org/#edition-1')
